# Encrypted Noir bot payload
# Runtime dependency: cryptography
# Render Environment Variable required: NOIR_KEY
# BOT_TOKEN remains read by the original Noir code from BOT_TOKEN.

import os
import base64
import hashlib
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.scrypt import Scrypt

_NOIR_SALT = 'UFGM/rFGDWdVRw8T3CNlFA=='
_NOIR_NONCE = 'WRZw91rDyvrXOeYy'
_NOIR_DATA = ''

_secret = os.environ.get("NOIR_KEY")
if not _secret:
    raise RuntimeError("NOIR_KEY environment variable is required.")

_kdf = Scrypt(
    salt=base64.b64decode(_NOIR_SALT),
    length=32,
    n=2**14,
    r=8,
    p=1,
)
_key = _kdf.derive(_secret.encode("utf-8"))
_code = AESGCM(_key).decrypt(
    base64.b64decode(_NOIR_NONCE),
    base64.b64decode(_NOIR_DATA),
    base64.b64decode(_NOIR_SALT),
)
exec(compile(_code, "Noir.py", "exec"), globals(), globals())
